  els.play.addEventListener('click',()=>state.playing?pause():play());els.stop.addEventListener('click',()=>stopPlayback());els.seek.addEventListener('input',()=>seek(Number(els.seek.value)/1000*duration()));els.speed.addEventListener('change',()=>{const wasPlaying=state.playing;if(wasPlaying){state.position=positionNow();state.startedPosition=state.position;state.startedAt=performance.now()}state.speed=Number(els.speed.value);audio.playbackRate=state.speed;if(wasPlaying){silenceNotes();state.nextNote=noteIndexAt(state.position)}updateSummary()});els.audioInput.addEventListener('change',e=>{if(e.target.files[0])loadAudio(e.target.files[0])});els.midiInput.addEventListener('change',e=>{if(e.target.files[0])loadMidi(e.target.files[0])});
